CREATE OR REPLACE TABLE daily_uniques (day DATE, hll sketch_hll);
INSERT INTO daily_uniques
SELECT date_trunc('day', ts) AS day,
       datasketch_hll(12, user_id) AS hll
FROM events
GROUP BY 1;

SELECT datasketch_hll_target_type(datasketch_hll(12, user_id, 'HLL_8')) AS encoding,
       datasketch_hll_estimate(datasketch_hll(12, user_id, 'HLL_8')) AS distinct_users
FROM events;

SELECT datasketch_hll_estimate(datasketch_hll_union(12, hll)) AS uniques_last_7d
FROM daily_uniques
WHERE day >= CURRENT_DATE - 7;

SELECT datasketch_theta_seed_hash(datasketch_theta(user_id, seed := 42)) AS seed_hash,
       datasketch_theta_get_theta(datasketch_theta(user_id, p := 0.5))      AS theta
FROM events;

WITH a AS (SELECT datasketch_theta(12, user_id) AS s FROM events_jan),
     b AS (SELECT datasketch_theta(12, user_id) AS s FROM events_feb)
SELECT datasketch_theta_estimate(
         datasketch_theta_intersect(a.s, b.s)
       ) AS retained_users
FROM a, b;

SELECT datasketch_frequent_items_get_frequent(
         datasketch_frequent_items(8, country_code),
         'NO_FALSE_POSITIVES'
       ) AS heavy_hitters
FROM page_views;

SELECT datasketch_frequent_items_get_frequent(
         datasketch_frequent_items_weighted(8, region, amount::BIGINT),
         'NO_FALSE_POSITIVES'
       ) AS by_revenue
FROM orders;

SELECT sv.item, sv.weight, sv.cumulative_weight
FROM (SELECT unnest(datasketch_kll_sorted_view(datasketch_kll(200, temp))) AS sv
      FROM readings);

SELECT datasketch_tdigest_quantile(
         datasketch_tdigest(100, latency_ms), 0.999
       ) AS p999
FROM requests;

SELECT datasketch_tdigest_min_value(datasketch_tdigest(100, temp)) AS min_temp,
       datasketch_tdigest_max_value(datasketch_tdigest(100, temp)) AS max_temp
FROM readings;

SELECT datasketch_req_is_hra(datasketch_req(12, value, false))                  AS hra,
       datasketch_req_quantile(datasketch_req(12, value, false), 0.01, true) AS p01
FROM measurements;
